  confusion:[
    {a:"Data Lifecycle Manager(DLM)",b:"AWS Backup",d:"DLM＝EBSスナップショット/AMIの作成・保持・削除をタグ＋スケジュールで自動化(EBS中心・手軽)。AWS Backup＝RDS/EFS/DynamoDB等も含めた複数サービス横断のバックアップ一元管理。EBSの世代管理だけならDLM、横断ならAWS Backup。"}
  ],
  terms:[
    {t:"Data Lifecycle Manager(DLM)",d:"タグで指定したEBSボリュームのスナップショットやAMIの作成・保持世代管理・削除を、ライフサイクルポリシーで自動化するサービス。"}
  ]
